            "definition": "CREATE OR REPLACE FUNCTION public.set_bayer_shipment_item_user_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.user_id is null then
    select s.user_id into new.user_id
    from public.bayer_shipments s
    where s.id = new.shipment_id;
  end if;

  if new.user_id is null then
    new.user_id := auth.uid();
  end if;

  return new;
end;
$function$
