column1:
            "definition": "CREATE OR REPLACE FUNCTION public.set_child_user_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_user uuid;
begin
  if new.user_id is not null then
    return new;
  end if;

  if new.order_id is not null then
    select o.user_id into v_user from public.orders o where o.id = new.order_id;
  end if;

  if v_user is null and new.customer_id is not null then
    select c.user_id into v_user from public.customers c where c.id = new.customer_id;
  end if;

  if v_user is null then
    v_user := auth.uid();
  end if;

  new.user_id := v_user;
  return new;
end;
$function$
"

            "definition": "CREATE OR REPLACE FUNCTION public.set_order_item_user_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.user_id is null then
    select o.user_id into new.user_id
    from public.orders o
    where o.id = new.order_id;
  end if;

  if new.user_id is null then
    new.user_id := auth.uid();
  end if;

  return new;
end;
$function$
"

            "definition": "CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
"

            "definition": "CREATE OR REPLACE FUNCTION public.set_user_id_from_auth()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.user_id is null then
    new.user_id := auth.uid();
  end if;
  return new;
end;
$function$
"

            "definition": "CREATE OR REPLACE FUNCTION public.set_year_end_verification_meta()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.is_verified is distinct from old.is_verified then
    if new.is_verified = true then
      new.verified_at := now();
      new.verified_by := auth.uid();
    else
      new.verified_at := null;
      new.verified_by := null;
    end if;
  end if;

  return new;
end;
$function$
"

